function searchFoods(keyword) {
  if (!keyword || typeof keyword !== 'string') return [];
  const q = keyword.trim().toLowerCase();
  return FOODS.filter(food => food.name.toLowerCase().includes(q));
}

function getFoodById(id) {
  return FOODS.find(food => food.id === id);
}

function calcNutrients(food, grams) {
  const ratio = grams / 100;
  const round1 = v => Math.round(v * 10) / 10;
  const round2 = v => Math.round(v * 100) / 100;
  return {
    calories: Math.round(food.calories * ratio),
    protein: round1(food.protein * ratio),
    carbs: round1(food.carbs * ratio),
    fat: round1(food.fat * ratio),
    fiber: round1(food.fiber * ratio),
    vitaminA: round1(food.vitaminA * ratio),
    vitaminC: round1(food.vitaminC * ratio),
    calcium: round1(food.calcium * ratio),
    magnesium: round1(food.magnesium * ratio),
    iron: round2(food.iron * ratio),
    zinc: round2(food.zinc * ratio)
  };
}

module.exports = { FOODS, searchFoods, getFoodById, calcNutrients };
